import { getAuthToken } from "@/features/auth/server-session";
import { serverApiFetch } from "@/lib/server-api";

// The BAL invoices are generated by "BusyWin" accounting software, which stamps
// the PDF /Title as UTF-16BE "BusyWin". Chrome shows a PDF's /Title as the tab
// name, so the raw PDF tab reads "BusyWin". We overwrite it in place with
// same-length "Invoice" (same byte count → xref offsets stay valid, no PDF
// re-encoding). This is only a fallback: the normal open path uses the titled
// wrapper below so the tab shows the actual invoice number.
const TITLE_FIND = [0, 0x42, 0, 0x75, 0, 0x73, 0, 0x79, 0, 0x57, 0, 0x69, 0, 0x6e]; // "BusyWin"
const TITLE_REPLACE = [0, 0x49, 0, 0x6e, 0, 0x76, 0, 0x6f, 0, 0x69, 0, 0x63, 0, 0x65]; // "Invoice"

/** Overwrite the first occurrence of `find` with `repl` (same length) in place. */
function replaceInPlace(buf: Uint8Array, find: number[], repl: number[]): void {
  outer: for (let i = 0; i + find.length <= buf.length; i++) {
    for (let j = 0; j < find.length; j++) {
      if (buf[i + j] !== find[j]) continue outer;
    }
    buf.set(repl, i);
    return;
  }
}

const HTML_ESCAPE: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};
const escapeHtml = (s: string): string => s.replace(/[&<>"']/g, (c) => HTML_ESCAPE[c]);

/**
 * Same-origin proxy that serves an invoice PDF.
 *
 * The API's `/invoice-files/:id` is role-scoped and needs a bearer token, so the
 * client used to fetch it with the token and open a `blob:` object URL — an ugly
 * `blob:https://…` in the address bar. Now the browser navigates straight here;
 * auth comes from the session cookie server-side (via `serverApiFetch`, which
 * uses the API service binding on Cloudflare). Two responses:
 *
 *  - default (no `?embed=1`): a tiny titled HTML page whose `<title>` is the
 *    invoice number, hosting the PDF in a full-viewport iframe. The browser tab
 *    shows the number we control — not the PDF's embedded "BusyWin" /Title.
 *  - `?embed=1`: the raw PDF (rendered inside that iframe), with the BusyWin
 *    title swapped to "Invoice" as a fallback.
 */
export async function GET(
  req: Request,
  ctx: { params: Promise<{ id: string }> },
): Promise<Response> {
  const { id } = await ctx.params;
  const url = new URL(req.url);

  const token = await getAuthToken();
  if (!token) return new Response("Unauthorized", { status: 401 });

  // Titled wrapper — the tab title source.
  if (url.searchParams.get("embed") !== "1") {
    const title = escapeHtml(url.searchParams.get("name") || "Invoice");
    const embedUrl = `/api/invoice-files/${encodeURIComponent(id)}?embed=1`;
    const html =
      `<!doctype html><html lang="en"><head><meta charset="utf-8">` +
      `<meta name="viewport" content="width=device-width, initial-scale=1">` +
      `<title>${title}</title>` +
      `<style>html,body{margin:0;height:100%;background:#525659}iframe{border:0;width:100%;height:100%;display:block}</style>` +
      `</head><body><iframe src="${embedUrl}" title="${title}"></iframe></body></html>`;
    return new Response(html, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "private, no-store",
      },
    });
  }

  const res = await serverApiFetch(`/invoice-files/${id}`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: "no-store",
  });
  if (!res.ok) {
    return new Response("Invoice PDF not available.", { status: res.status || 404 });
  }

  const buf = new Uint8Array(await res.arrayBuffer());
  replaceInPlace(buf, TITLE_FIND, TITLE_REPLACE);

  return new Response(buf, {
    headers: {
      "Content-Type": res.headers.get("Content-Type") ?? "application/pdf",
      // Inline so the PDF renders inside the iframe rather than downloading.
      "Content-Disposition": res.headers.get("Content-Disposition") ?? "inline",
      "Cache-Control": "private, no-store",
    },
  });
}
